pub fn fmt_g(v: f32) -> String {
    let x = v as f64;
    if x.is_nan() { return if x.is_sign_negative() { "-nan".into() } else { "nan".into() }; }
    if x.is_infinite() { return if x < 0.0 { "-inf".into() } else { "inf".into() }; }
    // get 6-significant-digit scientific form
    let sci = format!("{:.5e}", x); // "d.ddddde±X"
    let epos = sci.find('e').unwrap();
    let exp: i32 = sci[epos+1..].parse().unwrap();
    if exp < -4 || exp >= 6 {
        let mantissa = &sci[..epos]; // "-d.ddddd"
        let m = strip_zeros(mantissa);
        format!("{}e{}{:02}", m, if exp < 0 { '-' } else { '+' }, exp.abs())
    } else {
        let prec = (5 - exp) as usize;
        let s = format!("{:.*}", prec, x);
        strip_zeros(&s)
    }
}

fn strip_zeros(s: &str) -> String {
    if s.contains('.') {
        let t = s.trim_end_matches('0');
        let t = t.trim_end_matches('.');
        t.to_string()
    } else { s.to_string() }
}
```

