//! test20 — Rust port of the C++ ColorSpace test program.
//!
//! Builds 5 default colors, appends RGB triples parsed from argv
//! (std::stof semantics), and prints conversions/adjustments per color
//! using C++ `std::cout << float` (%g, 6 significant digits) formatting.

#[path = "src/color.rs"]
mod color;
#[path = "src/cppfmt.rs"]
mod cppfmt;
#[path = "src/stof.rs"]
mod stof;

use color::{ColorConverter, Rgb};
use cppfmt::fmt_g;

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let mut colors: Vec<Rgb> = vec![
        Rgb::new(0.1, 0.2, 0.3),
        Rgb::new(0.4, 0.5, 0.6),
        Rgb::new(0.7, 0.2, 0.1),
        Rgb::new(0.3, 0.8, 0.4),
        Rgb::new(0.9, 0.1, 0.8),
    ];

    // for (int i = 1; i + 2 < argc; i += 3)
    let mut i = 1usize;
    while i + 2 < args.len() {
        let r = stof::stof_or_abort(&args[i]);
        let g = stof::stof_or_abort(&args[i + 1]);
        let b = stof::stof_or_abort(&args[i + 2]);
        colors.push(Rgb::new(r, g, b));
        i += 3;
    }

    let mut out = String::new();
    for (idx, rgb) in colors.iter().enumerate() {
        let hsl = ColorConverter::rgb_to_hsl(rgb);
        let hsv = ColorConverter::rgb_to_hsv(rgb);
        let cmyk = ColorConverter::rgb_to_cmyk(rgb);
        let yuv = ColorConverter::rgb_to_yuv(rgb);

        let bright = ColorConverter::adjust_brightness(rgb, 1.2);
        let dark = ColorConverter::adjust_brightness(rgb, 0.8);
        let saturated = ColorConverter::adjust_saturation(rgb, 1.5);
        let gray = ColorConverter::grayscale(rgb);
        let inverted = ColorConverter::invert(rgb);

        out.push_str(&format!("Color {}: ", idx));
        for v in [rgb.r, rgb.g, rgb.b] {
            out.push_str(&fmt_g(v));
            out.push(' ');
        }
        for v in [hsl.h, hsl.s, hsl.l] {
            out.push_str(&fmt_g(v));
            out.push(' ');
        }
        for v in [hsv.h, hsv.s, hsv.v] {
            out.push_str(&fmt_g(v));
            out.push(' ');
        }
        for v in [cmyk.c, cmyk.m, cmyk.y, cmyk.k] {
            out.push_str(&fmt_g(v));
            out.push(' ');
        }
        for v in [yuv.y, yuv.u, yuv.v] {
            out.push_str(&fmt_g(v));
            out.push(' ');
        }
        for v in [bright.r, bright.g, bright.b] {
            out.push_str(&fmt_g(v));
            out.push(' ');
        }
        for v in [dark.r, dark.g, dark.b] {
            out.push_str(&fmt_g(v));
            out.push(' ');
        }
        for v in [saturated.r, saturated.g, saturated.b] {
            out.push_str(&fmt_g(v));
            out.push(' ');
        }
        for v in [gray.r, gray.g, gray.b] {
            out.push_str(&fmt_g(v));
            out.push(' ');
        }
        for v in [inverted.r, inverted.g, inverted.b] {
            out.push_str(&fmt_g(v));
            out.push(' ');
        }

        if idx == colors.len() - 1 && colors.len() > 1 {
            let dist = ColorConverter::color_distance(rgb, &colors[0]);
            out.push_str(&fmt_g(dist));
            out.push(' ');
        }

        out.push('\n');
    }
    print!("{}", out);
}

//! Color structs and conversions, ported black-box from the C++ ColorSpace
//! library behavior. All arithmetic is f32 to match C++ `float`.
//!
//! min/max are computed with sequential comparisons starting from `r`
//! (matches observed NaN propagation). Clamps are comparison-based so NaN
//! and -0.0 pass through unchanged, like C++ std::clamp.

#[derive(Clone, Copy, Debug)]
pub struct Rgb {
    pub r: f32,
    pub g: f32,
    pub b: f32,
}

#[derive(Clone, Copy, Debug)]
pub struct Hsl {
    pub h: f32,
    pub s: f32,
    pub l: f32,
}

#[derive(Clone, Copy, Debug)]
pub struct Hsv {
    pub h: f32,
    pub s: f32,
    pub v: f32,
}

#[derive(Clone, Copy, Debug)]
pub struct Cmyk {
    pub c: f32,
    pub m: f32,
    pub y: f32,
    pub k: f32,
}

#[derive(Clone, Copy, Debug)]
pub struct Yuv {
    pub y: f32,
    pub u: f32,
    pub v: f32,
}

impl Rgb {
    pub fn new(r: f32, g: f32, b: f32) -> Rgb {
        Rgb { r, g, b }
    }
}

/// C++ std::clamp(v, 0, 1): comparison-based, preserves NaN and -0.0.
fn clamp01(v: f32) -> f32 {
    if v < 0.0 {
        0.0
    } else if 1.0 < v {
        1.0
    } else {
        v
    }
}

pub struct ColorConverter;

impl ColorConverter {
    fn min_max(rgb: &Rgb) -> (f32, f32) {
        let mut min = rgb.r;
        if rgb.g < min {
            min = rgb.g;
        }
        if rgb.b < min {
            min = rgb.b;
        }
        let mut max = rgb.r;
        if rgb.g > max {
            max = rgb.g;
        }
        if rgb.b > max {
            max = rgb.b;
        }
        (min, max)
    }

    /// Shared hue computation (degrees). `d` must be max - min.
    fn hue(rgb: &Rgb, max: f32, d: f32) -> f32 {
        if d == 0.0 {
            return 0.0;
        }
        let mut h = if max == rgb.r {
            let mut h = (rgb.g - rgb.b) / d;
            if rgb.g < rgb.b {
                h += 6.0;
            }
            h
        } else if max == rgb.g {
            (rgb.b - rgb.r) / d + 2.0
        } else {
            (rgb.r - rgb.g) / d + 4.0
        };
        h *= 60.0;
        h
    }

    pub fn rgb_to_hsl(rgb: &Rgb) -> Hsl {
        let (min, max) = Self::min_max(rgb);
        let l = (max + min) / 2.0;
        let d = max - min;
        let mut h = 0.0f32;
        let mut s = 0.0f32;
        if d != 0.0 {
            s = if l > 0.5 {
                d / (2.0 - max - min)
            } else {
                d / (max + min)
            };
            h = Self::hue(rgb, max, d);
        }
        Hsl { h, s, l }
    }

    pub fn rgb_to_hsv(rgb: &Rgb) -> Hsv {
        let (min, max) = Self::min_max(rgb);
        let d = max - min;
        let s = if max == 0.0 { 0.0 } else { d / max };
        let h = Self::hue(rgb, max, d);
        Hsv { h, s, v: max }
    }

    pub fn rgb_to_cmyk(rgb: &Rgb) -> Cmyk {
        let (_, max) = Self::min_max(rgb);
        let k = 1.0 - max;
        if k == 1.0 {
            Cmyk {
                c: 0.0,
                m: 0.0,
                y: 0.0,
                k: 1.0,
            }
        } else {
            let t = 1.0 - k;
            Cmyk {
                c: (1.0 - rgb.r - k) / t,
                m: (1.0 - rgb.g - k) / t,
                y: (1.0 - rgb.b - k) / t,
                k,
            }
        }
    }

    pub fn rgb_to_yuv(rgb: &Rgb) -> Yuv {
        Yuv {
            y: 0.299 * rgb.r + 0.587 * rgb.g + 0.114 * rgb.b,
            u: -0.147 * rgb.r - 0.289 * rgb.g + 0.436 * rgb.b,
            v: 0.615 * rgb.r - 0.515 * rgb.g - 0.100 * rgb.b,
        }
    }

    pub fn adjust_brightness(rgb: &Rgb, factor: f32) -> Rgb {
        Rgb {
            r: clamp01(rgb.r * factor),
            g: clamp01(rgb.g * factor),
            b: clamp01(rgb.b * factor),
        }
    }

    pub fn adjust_saturation(rgb: &Rgb, factor: f32) -> Rgb {
        let mut hsl = Self::rgb_to_hsl(rgb);
        hsl.s = clamp01(hsl.s * factor);
        Self::hsl_to_rgb(&hsl)
    }

    pub fn grayscale(rgb: &Rgb) -> Rgb {
        let y = 0.2126 * rgb.r + 0.7152 * rgb.g + 0.0722 * rgb.b;
        Rgb {
            r: y,
            g: y,
            b: y,
        }
    }

    pub fn invert(rgb: &Rgb) -> Rgb {
        Rgb {
            r: 1.0 - rgb.r,
            g: 1.0 - rgb.g,
            b: 1.0 - rgb.b,
        }
    }

    pub fn color_distance(a: &Rgb, b: &Rgb) -> f32 {
        let dr = a.r - b.r;
        let dg = a.g - b.g;
        let db = a.b - b.b;
        (dr * dr + dg * dg + db * db).sqrt()
    }

    /// Standard HSL -> RGB via the hue2rgb helper (p/q formulation).
    fn hsl_to_rgb(hsl: &Hsl) -> Rgb {
        if hsl.s == 0.0 {
            Rgb {
                r: hsl.l,
                g: hsl.l,
                b: hsl.l,
            }
        } else {
            let h = hsl.h / 360.0;
            let q = if hsl.l < 0.5 {
                hsl.l * (1.0 + hsl.s)
            } else {
                hsl.l + hsl.s - hsl.l * hsl.s
            };
            let p = 2.0 * hsl.l - q;
            Rgb {
                r: Self::hue_to_rgb(p, q, h + 1.0 / 3.0),
                g: Self::hue_to_rgb(p, q, h),
                b: Self::hue_to_rgb(p, q, h - 1.0 / 3.0),
            }
        }
    }

    fn hue_to_rgb(p: f32, q: f32, mut t: f32) -> f32 {
        if t < 0.0 {
            t += 1.0;
        }
        if t > 1.0 {
            t -= 1.0;
        }
        if t < 1.0 / 6.0 {
            return p + (q - p) * 6.0 * t;
        }
        if t < 1.0 / 2.0 {
            return q;
        }
        if t < 2.0 / 3.0 {
            return p + (q - p) * (2.0 / 3.0 - t) * 6.0;
        }
        p
    }
}

//! C++ `std::cout << float` default formatting, i.e. printf("%g", (double)v)
//! with 6 significant digits:
//! - fixed notation when the decimal exponent X of the rounded value is in
//!   [-4, 5], scientific notation (two-digit minimum exponent) otherwise;
//! - trailing zeros stripped (and a bare trailing '.' removed);
//! - nan / -nan / inf / -inf, and -0 for negative zero.

/// Format an f32 exactly like C++ ostream's default float formatting.
pub fn fmt_g(v: f32) -> String {
    let x = v as f64;
    if x.is_nan() {
        return if x.is_sign_negative() {
            "-nan".to_string()
        } else {
            "nan".to_string()
        };
    }
    if x.is_infinite() {
        return if x < 0.0 { "-inf" } else { "inf" }.to_string();
    }

    // 6 significant digits in scientific form: "d.ddddde<exp>" or "-d.ddddde<exp>".
    let sci = format!("{:.5e}", x);
    let epos = sci.find('e').unwrap();
    let exp: i32 = sci[epos + 1..].parse().unwrap();

    if exp < -4 || exp >= 6 {
        let mantissa = strip_trailing_zeros(&sci[..epos]);
        format!(
            "{}e{}{:02}",
            mantissa,
            if exp < 0 { '-' } else { '+' },
            exp.abs()
        )
    } else {
        // %f with precision = 5 - exp, then strip trailing zeros.
        let prec = (5 - exp) as usize;
        let fixed = format!("{:.*}", prec, x);
        strip_trailing_zeros(&fixed)
    }
}

fn strip_trailing_zeros(s: &str) -> String {
    if s.contains('.') {
        let t = s.trim_end_matches('0');
        t.trim_end_matches('.').to_string()
    } else {
        s.to_string()
    }
}

//! Reimplementation of C++ std::stof (glibc strtof underneath):
//! - leading C whitespace skipped;
//! - optional '+'/'-' sign;
//! - "inf"/"infinity" and "nan" (case-insensitive);
//! - hexadecimal floats "0x1.8p1" (the 'p' exponent is optional for strtof);
//! - decimal floats with optional exponent; only the longest valid prefix is
//!   consumed ("0.5abc" -> 0.5, "1e" -> 1);
//! - no conversion possible -> std::invalid_argument -> terminate (SIGABRT);
//! - overflow or underflow (subnormal/zero result from a nonzero value)
//!   -> std::out_of_range -> terminate (SIGABRT).

pub enum StofError {
    Invalid,
    OutOfRange,
}

fn is_space(b: u8) -> bool {
    matches!(b, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
}

fn is_hex_digit(b: u8) -> bool {
    b.is_ascii_hexdigit()
}

fn hex_val(b: u8) -> u32 {
    (b as char).to_digit(16).unwrap()
}

fn starts_with_ci(bytes: &[u8], pat: &[u8]) -> bool {
    bytes.len() >= pat.len()
        && bytes
            .iter()
            .zip(pat.iter())
            .all(|(a, b)| a.to_ascii_lowercase() == *b)
}

pub fn stof(s: &str) -> Result<f32, StofError> {
    let b = s.as_bytes();
    let mut i = 0usize;
    while i < b.len() && is_space(b[i]) {
        i += 1;
    }
    let sign_start = i;
    let mut neg = false;
    if i < b.len() && (b[i] == b'+' || b[i] == b'-') {
        neg = b[i] == b'-';
        i += 1;
    }
    let rest = &b[i..];

    // inf / infinity
    if starts_with_ci(rest, b"infinity") || starts_with_ci(rest, b"inf") {
        return Ok(if neg {
            f32::NEG_INFINITY
        } else {
            f32::INFINITY
        });
    }
    // nan
    if starts_with_ci(rest, b"nan") {
        let v = f32::NAN;
        return Ok(if neg { -v } else { v });
    }

    // hexadecimal float: 0x<hex>[.<hex>][p[+-]dec]
    if rest.len() >= 2
        && rest[0] == b'0'
        && (rest[1] | 0x20) == b'x'
        && (rest.len() >= 3 && (is_hex_digit(rest[2])
            || (rest[2] == b'.' && rest.len() >= 4 && is_hex_digit(rest[3]))))
    {
        let mut j = 2usize;
        let mut mant: f64 = 0.0;
        let mut int_digits = 0u32; // integer hex digits folded into mantissa
        let mut extra_int = 0i32; // integer hex digits beyond mantissa capacity
        while j < rest.len() && is_hex_digit(rest[j]) {
            if int_digits < 13 {
                mant = mant * 16.0 + hex_val(rest[j]) as f64;
                int_digits += 1;
            } else {
                extra_int += 1;
            }
            j += 1;
        }
        let mut frac_digits = 0i32;
        if j < rest.len() && rest[j] == b'.' {
            j += 1;
            while j < rest.len() && is_hex_digit(rest[j]) {
                if int_digits < 13 {
                    mant = mant * 16.0 + hex_val(rest[j]) as f64;
                    int_digits += 1;
                }
                frac_digits += 1;
                j += 1;
            }
        }
        let mut pexp: i64 = 0;
        if j < rest.len() && (rest[j] | 0x20) == b'p' {
            let mut k = j + 1;
            let mut pneg = false;
            if k < rest.len() && (rest[k] == b'+' || rest[k] == b'-') {
                pneg = rest[k] == b'-';
                k += 1;
            }
            let dstart = k;
            let mut val: i64 = 0;
            while k < rest.len() && rest[k].is_ascii_digit() {
                val = (val * 10 + (rest[k] - b'0') as i64).min(100_000);
                k += 1;
            }
            if k > dstart {
                pexp = if pneg { -val } else { val };
            }
        }
        let exp2 = pexp + 4 * (extra_int as i64 - frac_digits as i64);
        let v = mant * 2f64.powi(exp2.clamp(-4000, 4000) as i32);
        let v = if neg { -v } else { v };
        return range_check(v, v != 0.0);
    }

    // decimal float: digits[.digits][e[+-]digits] or .digits[e...]
    let mut j = 0usize;
    let mut int_digits = 0usize;
    while j < rest.len() && rest[j].is_ascii_digit() {
        j += 1;
        int_digits += 1;
    }
    let mut frac_digits = 0usize;
    let mut frac_end = j;
    if j < rest.len() && rest[j] == b'.' {
        let mut k = j + 1;
        while k < rest.len() && rest[k].is_ascii_digit() {
            k += 1;
            frac_digits += 1;
        }
        if int_digits > 0 || frac_digits > 0 {
            frac_end = k;
        }
    }
    if int_digits == 0 && frac_digits == 0 {
        return Err(StofError::Invalid);
    }
    let mut end = frac_end;
    // optional exponent (back up if it has no digits)
    if end < rest.len() && (rest[end] | 0x20) == b'e' {
        let mut k = end + 1;
        if k < rest.len() && (rest[k] == b'+' || rest[k] == b'-') {
            k += 1;
        }
        let dstart = k;
        while k < rest.len() && rest[k].is_ascii_digit() {
            k += 1;
        }
        if k > dstart {
            end = k;
        }
    }

    let prefix = &s[sign_start..i + end];
    // Rust's f32 parser is correctly rounded, like strtof.
    let parse_target = prefix.strip_suffix('.').unwrap_or(prefix);
    let v: f32 = parse_target.parse().map_err(|_| StofError::Invalid)?;

    // Detect nonzero mantissa (for underflow detection without double parse).
    let nonzero = prefix
        .bytes()
        .take_while(|c| *c != b'e' && *c != b'E')
        .any(|c| (b'1'..=b'9').contains(&c));
    range_check(v as f64, nonzero)
}

/// glibc strtof sets ERANGE on overflow (result inf from finite input) and on
/// underflow (rounded result zero or subnormal while the value is nonzero);
/// std::stof then throws std::out_of_range.
fn range_check(v64: f64, nonzero: bool) -> Result<f32, StofError> {
    let v = v64 as f32;
    if v.is_infinite() {
        return Err(StofError::OutOfRange);
    }
    let a = v.abs();
    if nonzero && (a == 0.0 || a < f32::MIN_POSITIVE) {
        return Err(StofError::OutOfRange);
    }
    Ok(v)
}

/// Parse like std::stof; on failure mimic the C++ program: an uncaught
/// exception aborts the process (SIGABRT, exit code 134).
pub fn stof_or_abort(s: &str) -> f32 {
    match stof(s) {
        Ok(v) => v,
        Err(StofError::Invalid) => abort_like("std::invalid_argument"),
        Err(StofError::OutOfRange) => abort_like("std::out_of_range"),
    }
}

fn abort_like(exc: &str) -> ! {
    eprintln!("terminate called after throwing an instance of '{}'", exc);
    eprintln!("  what():  stof");
    std::process::abort();
}

